    "valuation": "Up to $320M enterprise value",
    "note": "Going public by merging with FACT II Acquisition Corp (NASDAQ: FACT), announced June 2026. Also signed an LOI to bolt on a telecom/surveillance/structural-steel defense supplier (~$12M revenue)."
